import XCTest
@testable import LoopStrapEngine
import Foundation

// MARK: - Advice parity tests

/// Oracle parity tests for Phase 7 AdviceEngine.
///
/// Validates that `AdviceEngine.compute()` produces the same advice codes and
/// numeric params as the Python `advice.py compute_advice()` oracle, using
/// the 5-case fixture generated by `scripts/export_advice_fixtures.py`.
///
/// Fixture format: Resources/fixtures/advice/compute_advice.json
/// Each case has `inputs` + `expected` (not the generic `output` field used by
/// other parity tests — advice fixtures use a domain-specific expected structure).
final class AdviceParityTests: XCTestCase {

    // MARK: - Advice parity

    func testAdviceSignalParity() throws {
        let config = try ToleranceConfig.load()
        let tolerance = config.spec(for: "compute_advice")

        let url = try resourceURL("compute_advice", "json")
        let data = try Data(contentsOf: url)
        let file = try JSONDecoder().decode(AdviceFixtureFile.self, from: data)

        XCTAssertEqual(file.module, "advice",
                       "fixture module must be 'advice'")
        XCTAssertGreaterThan(file.cases.count, 0,
                             "fixture must contain at least one case")

        for testCase in file.cases {
            let inputs = testCase.inputs
            let expected = testCase.expected

            // ── Decode recovery ───────────────────────────────────────────────
            let recovery = RecoveryResult(
                score:      inputs.recovery.score,
                band:       inputs.recovery.band,
                confidence: inputs.recovery.confidence,
                zHrv: nil, zRhr: nil, zResp: nil
            )

            // ── Decode sleep history (nullable doubles) ────────────────────────
            let sleepHistory: [Double?] = inputs.sleepHistory.map { $0 }

            // ── Decode optional baselines ─────────────────────────────────────
            let durationBaseline   = inputs.durationBaseline.map(makeBaselineState)
            let bedtimeBaseline    = inputs.bedtimeBaseline.map(makeBaselineState)
            let strainBaseline     = inputs.strainBaseline.map(makeBaselineState)
            let recentStrainHistory: [Double?] = inputs.recentStrainHistory.map { $0 }

            // ── Call AdviceEngine ─────────────────────────────────────────────
            let result = AdviceEngine.compute(
                recovery:             recovery,
                sleepHistory:         sleepHistory,
                durationBaseline:     durationBaseline,
                bedtimeBaseline:      bedtimeBaseline,
                tonightBedtimeOffset: inputs.tonightBedtimeOffset,
                strainBaseline:       strainBaseline,
                recentStrainHistory:  recentStrainHistory
            )

            // ── Assert primary code (exact string match) ──────────────────────
            XCTAssertEqual(result.primaryCode.rawValue, expected.primaryCode,
                           "case \(testCase.name): primaryCode mismatch")

            // ── Assert primary confidence (exact string match) ────────────────
            XCTAssertEqual(result.primaryConfidence, expected.primaryConfidence,
                           "case \(testCase.name): primaryConfidence mismatch")

            // ── Assert primary params numeric fields ──────────────────────────
            for (key, expectedValue) in expected.primaryParams {
                if let actualValue = result.primaryParams[key] {
                    assertParity(actual: actualValue, expected: expectedValue,
                                 tolerance: tolerance,
                                 file: #filePath, line: #line)
                } else {
                    XCTFail("case \(testCase.name): primaryParams missing key '\(key)'")
                }
            }

            // ── Assert secondary signal codes present ─────────────────────────
            for expectedSignal in expected.secondary {
                XCTAssertTrue(
                    result.secondary.contains { $0.code == expectedSignal.code },
                    "case \(testCase.name): secondary missing code '\(expectedSignal.code)'"
                )
            }

            // ── Assert secondary numeric params (debt_min, target_strain) ─────
            for expectedSignal in expected.secondary {
                guard let actualSignal = result.secondary.first(where: { $0.code == expectedSignal.code })
                else { continue }

                // Decode both sides as JSON dicts for numeric comparison.
                let expectedParams = parseParamsJSON(expectedSignal.paramsJSON)
                let actualParams   = parseParamsJSON(actualSignal.paramsJSON)

                for (key, expectedValue) in expectedParams {
                    // Loop deliberately differs from the legacy oracle: without an adequate
                    // reference, overload is unknown rather than an asserted false value.
                    if key == "recent_overload", strainBaseline?.usable != true || recentStrainHistory.compactMap({ $0 }).isEmpty {
                        XCTAssertNil(actualParams[key])
                        continue
                    }
                    if let actualValue = actualParams[key] {
                        assertParity(actual: actualValue, expected: expectedValue,
                                     tolerance: tolerance,
                                     file: #filePath, line: #line)
                    } else {
                        XCTFail("case \(testCase.name) signal '\(expectedSignal.code)': params missing key '\(key)'")
                    }
                }
            }
        }
    }

    // MARK: - Helpers

    /// Build a `BaselineState` from a fixture baseline dict.
    private func makeBaselineState(_ b: AdviceBaselineFixture) -> BaselineState {
        let status: BaselineStatus = BaselineStatus(rawValue: b.status) ?? BaselineStatus.calibrating
        return BaselineState(
            baseline:          b.baseline,
            spread:            b.spread,
            nValid:            b.nValid,
            nightsSinceUpdate: b.nightsSinceUpdate,
            status:            status
        )
    }

    /// Parse a JSON params string → `[String: Double]` (numeric keys only, booleans skipped).
    ///
    /// Used to compare secondary signal params field-by-field without committing to
    /// a fixed key set (different codes have different param shapes).
    private func parseParamsJSON(_ json: String) -> [String: Double] {
        guard let data = json.data(using: .utf8),
              let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        else { return [:] }
        var result: [String: Double] = [:]
        for (key, value) in obj {
            if let d = value as? Double {
                result[key] = d
            } else if let i = value as? Int {
                result[key] = Double(i)
            }
            // Bool keys (e.g. "recent_overload") are intentionally skipped —
            // they are not compared with assertParity.
        }
        return result
    }
}

// MARK: - Advice fixture types

/// Top-level structure of compute_advice.json.
///
/// The advice fixture uses a domain-specific `expected` key instead of the generic
/// `output` key used by other parity fixtures (DailyParityTests, HRVParityTests, etc.).
private struct AdviceFixtureFile: Decodable {
    let module: String
    let function: String
    let oracleGitSha: String
    let cases: [AdviceFixtureCase]

    private enum CodingKeys: String, CodingKey {
        case module, function, cases
        case oracleGitSha = "oracle_git_sha"
    }
}

private struct AdviceFixtureCase: Decodable {
    let name: String
    let inputs: AdviceInputsFixture
    let expected: AdviceExpectedFixture
}

private struct AdviceInputsFixture: Decodable {
    let recovery: AdviceRecoveryFixture
    let sleepHistory: [Double?]
    let durationBaseline: AdviceBaselineFixture?
    let bedtimeBaseline: AdviceBaselineFixture?
    let tonightBedtimeOffset: Double?
    let strainBaseline: AdviceBaselineFixture?
    let recentStrainHistory: [Double?]

    private enum CodingKeys: String, CodingKey {
        case recovery
        case sleepHistory         = "sleep_history"
        case durationBaseline     = "duration_baseline"
        case bedtimeBaseline      = "bedtime_baseline"
        case tonightBedtimeOffset = "tonight_bedtime_offset"
        case strainBaseline       = "strain_baseline"
        case recentStrainHistory  = "recent_strain_history"
    }
}

private struct AdviceRecoveryFixture: Decodable {
    let score: Double?
    let band: String?
    let confidence: String
}

private struct AdviceBaselineFixture: Decodable {
    let baseline: Double
    let spread: Double
    let nValid: Int
    let nightsSinceUpdate: Int
    let status: String
    let usable: Bool

    private enum CodingKeys: String, CodingKey {
        case baseline, spread, status, usable
        case nValid            = "n_valid"
        case nightsSinceUpdate = "nights_since_update"
    }
}

private struct AdviceExpectedFixture: Decodable {
    let primaryCode: String
    let primaryParams: [String: Double]
    let primaryConfidence: String
    let secondary: [AdviceSecondaryFixture]

    private enum CodingKeys: String, CodingKey {
        case primaryCode       = "primary_code"
        case primaryParams     = "primary_params"
        case primaryConfidence = "primary_confidence"
        case secondary
    }
}

private struct AdviceSecondaryFixture: Decodable {
    let code: String
    let paramsJSON: String
    let confidence: String

    private enum CodingKeys: String, CodingKey {
        case code, confidence
        case paramsJSON = "params_json"
    }
}
